###################################################################################
# DATA GENERATED BY AI
###################################################################################

using MissingDataViz
using DataFrames
using Random
using Dates 

println("="^70)
println("COMPLETE TEST - PART 3: DESCRIPTIVE STATISTICS")
println("="^70)

# ============================================================================
# BASELINE DATASET GENERATION (for robustness)
# ============================================================================

# Seed for reproducibility
Random.seed!(42)

# Create a realistic dataset simulating medical data
n_patients = 100
df_medical = DataFrame(
    PatientID = 1:n_patients,
    Age = rand([25, 30, 35, 40, 45, 50, missing], n_patients),
    BloodPressure = rand([120, 130, 140, missing], n_patients),
    Cholesterol = rand([180, 200, 220, 240, missing, missing], n_patients),
    BMI = rand([22.5, 25.0, 27.5, 30.0, missing], n_patients),
    Smoker = rand([true, false, missing], n_patients),
    
    # Completely missing column (collection error)
    BloodType = fill(missing, n_patients),
    
    # Completely present column (always collected)
    VisitDate = fill(Date(2024, 1, 1), n_patients)
)

println("\nDataset: $(nrow(df_medical)) patients × $(ncol(df_medical)) variables")
println("\nFirst rows:")
println(first(df_medical, 5))

# =============================
# TEST 1: row_missing_stats
# =============================
println("\n" * "="^70)
println("TEST 1: STATISTICS BY ROW")
println("="^70)

row_stats = row_missing_stats(df_medical)
println("\nStatistics by patient (first 5):")
for i in 1:5
    println("  Patient $i: $(round(row_stats[i], digits=1))% missing data")
end

# Identify patients with a lot of missing
problematic = findall(x -> x > 50, row_stats)
println("\nPatients with >50% missing data: $(length(problematic))")
if length(problematic) > 0
    println("  Indices: ", problematic[1:min(10, length(problematic))])
end

# =============================
# TEST 2: column_missing_distribution
# =============================
println("\n" * "="^70)
println("TEST 2: DISTRIBUTION BY COLUMN")
println("="^70)

col_dist = column_missing_distribution(df_medical)
println("\nComplete distribution:")
println(col_dist)

println("\nTop 3 columns with most missing:")
sorted_cols = sort(col_dist, :pct_missing, rev=true)
println(first(sorted_cols, 3))

# =============================
# TEST 3: extreme_patterns
# =============================
println("\n" * "="^70)
println("TEST 3: EXTREME PATTERNS")
println("="^70)

extremes = extreme_patterns(df_medical)

println("\n100% missing rows: $(length(extremes.rows_all_missing))")
if length(extremes.rows_all_missing) > 0
    println("  Indices: ", extremes.rows_all_missing[1:min(5, length(extremes.rows_all_missing))])
end

println("\n100% complete rows: $(length(extremes.rows_all_complete))")
if length(extremes.rows_all_complete) > 0
    println("  Indices: ", extremes.rows_all_complete[1:min(5, length(extremes.rows_all_complete))])
end

println("\n100% missing columns: $(length(extremes.cols_all_missing))")
if length(extremes.cols_all_missing) > 0
    println("  Columns: ", names(df_medical)[extremes.cols_all_missing])
end

println("\n100% complete columns: $(length(extremes.cols_all_complete))")
if length(extremes.cols_all_complete) > 0
    println("  Columns: ", names(df_medical)[extremes.cols_all_complete])
end

# =============================
# TEST 4: summarize_missing (ALL-IN-ONE)
# =============================
println("\n" * "="^70)
println("TEST 4: GLOBAL SUMMARY (ALL-IN-ONE)")
println("="^70)

summary = summarize_missing(df_medical)

println("\nGLOBAL OVERVIEW")
println("  Total cells: ", summary.total_cells)
println("  Missing values: ", summary.n_missing)
println("  Global percentage: ", summary.pct_missing, "%")

println("\nTOP 5 MOST FREQUENT PATTERNS")
for (i, (pattern, count)) in enumerate(summary.top_patterns)
    pct = round(count / nrow(df_medical) * 100, digits=1)
    println("  $i. Pattern ", Int.(pattern), " → $count patients ($pct%)")
end

println("\nDETECTED EXTREME CASES")
println("  Patients to remove (100% missing): ", length(summary.extremes.rows_all_missing))
println("  Columns to remove (100% missing): ", length(summary.extremes.cols_all_missing))
if length(summary.extremes.cols_all_missing) > 0
    println("    → ", names(df_medical)[summary.extremes.cols_all_missing])
end

println("\nRELIABLE COLUMNS (100% complete)")
println("  Count: ", length(summary.extremes.cols_all_complete))
if length(summary.extremes.cols_all_complete) > 0
    println("    → ", names(df_medical)[summary.extremes.cols_all_complete])
end

# =============================
# TEST 5: AUTOMATIC DECISIONS
# =============================
println("\n" * "="^70)
println("TEST 5: AUTOMATIC RECOMMENDATIONS")
println("="^70)

println("\nANALYSIS AND RECOMMENDATIONS:")

# Recommendation 1: Columns to remove
if length(summary.extremes.cols_all_missing) > 0
    println("\nRemove these columns (100% missing):")
    for col_idx in summary.extremes.cols_all_missing
        println("     - ", names(df_medical)[col_idx])
    end
end

# Recommendation 2: Problematic columns (>50% missing)
high_missing_cols = summary.by_column[summary.by_column.pct_missing .> 50, :]
if nrow(high_missing_cols) > 0
    println("\nColumns with >50% missing (difficult imputation):")
    for row in eachrow(high_missing_cols)
        println("     - $(row.column_name): $(round(row.pct_missing, digits=1))%")
    end
end

# Recommendation 3: Patients to investigate
high_missing_patients = findall(x -> x > 60, summary.by_row)
if length(high_missing_patients) > 0
    println("\nPatients with >60% missing (to verify):")
    println("     Total count: ", length(high_missing_patients))
    println("     Examples: Patient ", high_missing_patients[1:min(5, length(high_missing_patients))])
end

# Recommendation 4: Global quality
println("\nDATASET GLOBAL QUALITY:")
if summary.pct_missing < 5
    println("EXCELLENT (< 5% missing)")
elseif summary.pct_missing < 15
    println("GOOD (5-15% missing)")
elseif summary.pct_missing < 30
    println("AVERAGE (15-30% missing)")
else
    println("PROBLEMATIC (> 30% missing)")
end

println("\n" * "="^70)
println("ALL TESTS PASSED - PART 3 VALIDATED")
println("="^70)

